import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

const PANE = 'ideas-shelf'
const TITLE = 'Ideas Shelf'
const FILE = 'IDEAS.md'
const HEADER = ['# Ideias', '']
const BAR = 10
// One idea is one markdown task line: "- [ ] text" or "- [x] text".
const TASK = /^(\s*[-*] \[)([ xX])(\] )(.*)$/

const shelf = atom({ plugin: 'ideas-shelf', key: 'shelf' } as const, {
  path: '',
  lines: [],
})

// Counts the ideas added from the field: the field's key carries it, so each
// add draws a fresh, empty field.
const added = atom({ plugin: 'ideas-shelf', key: 'added' } as const, 0)

const readLines = async ($: EngineInterface, path: string) => {
  if (!(await $.fs.exists(path))) {
    return []
  }
  const lines = (await $.fs.read(path)).split(/\r?\n/)
  while (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  return lines
}

// The project's file is the truth: the shelf is re-read before it is shown
// and before every change, so edits made by hand or by Claude are kept.
const load = async ($: EngineInterface) => {
  const path = `${await $.session.root()}/${FILE}`
  const lines = await readLines($, path)
  await update($, shelf, () => ({ path, lines }))

  return { path, lines }
}

const change = async (
  $: EngineInterface,
  edit: (lines: string[]) => string[] | undefined,
) => {
  const { path, lines } = await load($)
  const edited = edit(lines.length === 0 ? [...HEADER] : [...lines])
  if (edited === undefined) {
    $.ui.toast('Essa ideia mudou no arquivo; a lista foi atualizada.')

    return false
  }
  await $.fs.write(path, `${edited.join('\n')}\n`)
  await update($, shelf, () => ({ path, lines: edited }))

  return true
}

const add = ($: EngineInterface, text: string) => {
  const idea = text.replace(/\s+/g, ' ').trim()
  if (idea === '') {
    return Promise.resolve(false)
  }

  return change($, lines => [...lines, `- [ ] ${idea}`])
}

// A row is addressed by the line it was drawn from; if the file moved under
// it, the same line is looked up again before anything is touched.
const locate = (lines: string[], index: number, line: string) =>
  lines[index] === line ? index : lines.indexOf(line)

const toggle = ($: EngineInterface, index: number, line: string) =>
  change($, lines => {
    const at = locate(lines, index, line)
    if (at < 0) {
      return undefined
    }
    lines[at] = line.replace(
      TASK,
      (_, head: string, mark: string, tail: string, text: string) =>
        `${head}${mark === ' ' ? 'x' : ' '}${tail}${text}`,
    )

    return lines
  })

const remove = ($: EngineInterface, index: number, line: string) =>
  change($, lines => {
    const at = locate(lines, index, line)
    if (at < 0) {
      return undefined
    }
    lines.splice(at, 1)

    return lines
  })

// Sent as the person's own words; the turn starts once the session is idle.
const send = ($: EngineInterface, text: string) => {
  void $.prompt.submit({ text, asUser: true })
  $.ui.toast('Ideia enviada ao chat.')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'ideas',
      description: 'Abre a prateleira de ideias deste projeto',
    })
    await $.command.register({
      name: 'idea',
      description: 'Guarda uma ideia na prateleira deste projeto',
      argumentHint: '<texto da ideia>',
    })
    await load($)

    return next(e)
  })

  on('command.run', { command: 'ideas' }, async $ => {
    await load($)
    await $.ui.open({ id: PANE, title: TITLE, focus: true })

    return { text: 'Ideas Shelf aberto.' }
  })

  on('command.run', { command: 'idea' }, async ($, e) => {
    if (e.args.trim() === '') {
      await load($)
      await $.ui.open({ id: PANE, title: TITLE, focus: true })

      return { text: 'Ideas Shelf aberto. Use /idea <texto> para guardar direto.' }
    }
    await add($, e.args)

    return { text: `Ideia guardada em ${FILE}: ${e.args.trim()}` }
  })

  // Claude may have edited IDEAS.md, or the session may have moved project.
  on('turn.complete', async ($, e, next) => {
    await load($)

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    const Input = e.surface === 'mobile' ? undefined : $.ui.resolve(e).Input
    const { lines } = await read($, shelf)
    const field = await read($, added)
    const ideas = lines.flatMap((line, index) => {
      const task = TASK.exec(line)

      return task === null
        ? []
        : [{ index, line, isDone: task[2] !== ' ', text: task[4] ?? '' }]
    })
    const open = ideas.filter(idea => !idea.isDone)
    const done = ideas.filter(idea => idea.isDone)
    const filled =
      ideas.length === 0 ? 0 : Math.round((done.length / ideas.length) * BAR)
    const actions = (idea: (typeof ideas)[number]) => (
      <Box flexShrink={0} gap={1}>
        {!idea.isDone && (
          <Button
            key={`send:${idea.index}`}
            plain
            dimColor
            hover={{ dimColor: false, color: 'suggestion' }}
            onPress={() => {
              send($, idea.text)
            }}
          >
            ➤
          </Button>
        )}
        <Button
          key={`remove:${idea.index}`}
          plain
          dimColor
          hover={{ dimColor: false, color: 'error' }}
          onPress={() => {
            void remove($, idea.index, idea.line)
          }}
        >
          ✕
        </Button>
      </Box>
    )

    return (
      <Box flexDirection="column" paddingX={1} gap={1}>
        <Box justifyContent="space-between">
          <Text bold>{TITLE}</Text>
          {ideas.length > 0 && (
            <Text>
              <Text color="success">{'▰'.repeat(filled)}</Text>
              <Text dimColor>{'▱'.repeat(BAR - filled)}</Text>
              <Text dimColor>
                {' '}
                {done.length}/{ideas.length} feitas
              </Text>
            </Text>
          )}
        </Box>
        {Input !== undefined && (
          <Input
            key={`new:${field}`}
            label="＋"
            placeholder="Anote uma ideia e pressione Enter"
            value=""
            submitLabel="guardar"
            autoFocus
            onSubmit={value => {
              void add($, value).then(isAdded =>
                isAdded ? update($, added, count => count + 1) : undefined,
              )
            }}
          />
        )}
        {ideas.length === 0 && (
          <Box flexDirection="column" alignItems="center" paddingY={1}>
            <Text dimColor>A prateleira está vazia.</Text>
            <Text dimColor>Anote acima ou use /idea &lt;texto&gt; no chat.</Text>
          </Box>
        )}
        {ideas.length > 0 && (
          <Box flexDirection="column">
            <Text bold color="suggestion">
              PENDENTES <Text dimColor>· {open.length}</Text>
            </Text>
            {open.length === 0 && (
              <Text dimColor>Tudo feito por aqui.</Text>
            )}
            {open.map(idea => (
              <Box
                key={`row:${idea.index}`}
                justifyContent="space-between"
                gap={2}
                paddingX={1}
                borderStyle="round"
                borderDimColor
                hover={{ borderColor: 'suggestion' }}
              >
                <Box flexGrow={1} flexShrink={1} gap={1}>
                  <Box flexShrink={0}>
                    <Button
                      key={`toggle:${idea.index}`}
                      plain
                      onPress={() => {
                        void toggle($, idea.index, idea.line)
                      }}
                    >
                      <Text bold color="claude">
                        ○
                      </Text>
                    </Button>
                  </Box>
                  <Text>{idea.text}</Text>
                </Box>
                {actions(idea)}
              </Box>
            ))}
          </Box>
        )}
        {done.length > 0 && (
          <Box flexDirection="column">
            <Text bold color="success">
              FEITAS <Text dimColor>· {done.length}</Text>
            </Text>
            {done.map(idea => (
              <Box
                key={`row:${idea.index}`}
                justifyContent="space-between"
                gap={2}
                paddingX={1}
                borderStyle="round"
                borderDimColor
                hover={{ borderColor: 'success' }}
              >
                <Box flexGrow={1} flexShrink={1} gap={1}>
                  <Box flexShrink={0}>
                    <Button
                      key={`toggle:${idea.index}`}
                      plain
                      onPress={() => {
                        void toggle($, idea.index, idea.line)
                      }}
                    >
                      <Text bold color="success">
                        ✓
                      </Text>
                    </Button>
                  </Box>
                  <Text dimColor strikethrough>
                    {idea.text}
                  </Text>
                </Box>
                {actions(idea)}
              </Box>
            ))}
          </Box>
        )}
        <Text dimColor>
          ○ marca como feita · ➤ envia ao chat · ✕ remove · {FILE}
        </Text>
      </Box>
    )
  })
}

